// newInput builds the insert a Batch queues for in under parent, and
// the record it stands for, named: the same resolution Create applies.
func (r *GraphQLAvailabilityRepository) newInput(parent string, in *availabilityv1.Availability) (availabilitiesql.CreateInput, *availabilityv1.Availability, error) {
	var ci availabilitiesql.CreateInput
	parentIDs, err := repox.SplitName(parent, "calendars")
	if err != nil {
		return ci, nil, err
	}
	id := repox.NewULID()
	rowID := id
	if in.GetName() != "" {
		ids, err := repox.SplitName(in.GetName(), "calendars", "availabilities")
		if err != nil {
			return ci, nil, err
		}
		for i := range parentIDs {
			if ids[i] != parentIDs[i] {
				return ci, nil, fmt.Errorf("%w: name %q is not under parent %q", repox.ErrInvalidArgument, in.GetName(), parent)
			}
		}
		id = ids[len(ids)-1]
	}
	in = proto.Clone(in).(*availabilityv1.Availability)
	in.Name = FormatAvailabilityName(parentIDs[0], id)
	id = rowID // keyed as Create keys it
	ci = availabilityToCreateInput(in)
	ci.Id = id
	ci.CalendarId = parentIDs[0]
	ci.Etag = repox.NewULID()
	now := tsToStr(timestamppb.New(time.Now().UTC()))
	ci.CreateTime = now
	ci.UpdateTime = now
	return ci, in, nil
}

