// updateOps queues Update's writes onto ops, for a Batch: the value-object
// rows that replace the masked ones, the row update, then the removal of what
// they replaced. With in.Etag set the update is guarded inside the batch: a
// self-update of the key whose post-check asserts the etag fails the request
// when the record moved on, and the guarded update after it writes the row.
//
// outputPaths names the server-owned fields written alongside
// (Update<Model>WithOutputOnly); nil for Update.
func (r *GraphQLAvailabilityRepository) updateOps(ctx context.Context, ops *repox.Ops, id string, in *availabilityv1.Availability, paths, outputPaths []string) (repox.Check, error) {
	row, err := r.Svc.Query.Availability.Availabilities.Get(ctx, id)
	if err != nil {
		return nil, mapGraphQLErr(err)
	}
	if row == nil {
		return nil, repox.ErrNotFound
	}
	existingPB := availabilityFromRow(row)
	if in.GetEtag() != "" && existingPB.GetEtag() != in.GetEtag() {
		return nil, repox.ErrConflict
	}
	var staleStart string
	var staleEnd string
	var old21 []string
	{
		rows22, err := r.Svc.Query.Availability.AvailablePeriods.List(ctx, availableperiodsql.List().Where(availableperiodsql.AvailabilityId.Eq(id)))
		if err != nil {
			return nil, mapGraphQLErr(err)
		}
		for i := range rows22 {
			old21 = append(old21, rows22[i].Id)
		}
	}
	staleAvailablePeriods := old21
	merged := proto.Clone(existingPB).(*availabilityv1.Availability)
	applyAvailabilityMask(merged, in, paths)
	repox.CopyFields(merged, in, outputPaths)
	patch := availabilityToUpdatePatch(merged)
	if len(outputPaths) > 0 {
		availabilityAddOutputPatch(&patch, merged, outputPaths)
	}
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	var utx, atx repox.Ops
	if repox.GroupTouched(paths, "start") {
		staleStart = repox.Deref(row.StartId)
		patch.StartId = graphql.Null[string]()
		if v := merged.GetStart(); v != nil {
			vi := availabilityCalendarTimeToCreateInput(v)
			vi.Id = repox.NewULID()
			utx.Add(r.Svc.Mutation.Availability.CalendarTimes.CreateOp(vi, new(calendartimesql.InsertAvailabilityCalendarTimesResponse)))
			patch.StartId = graphql.Value(vi.Id)
		}
	}
	if repox.GroupTouched(paths, "end") || repox.GroupTouched(paths, "duration") {
		staleEnd = repox.Deref(row.EndId)
		patch.EndId = graphql.Null[string]()
		if v := merged.GetEnd(); v != nil {
			vi := availabilityCalendarTimeToCreateInput(v)
			vi.Id = repox.NewULID()
			utx.Add(r.Svc.Mutation.Availability.CalendarTimes.CreateOp(vi, new(calendartimesql.InsertAvailabilityCalendarTimesResponse)))
			patch.EndId = graphql.Value(vi.Id)
			patch.EndFormCase = graphql.Value("END")
		}
	}
	if repox.GroupTouched(paths, "available_periods") {
		for _, oid := range staleAvailablePeriods {
			if id := oid; id != "" {
				got23, err := r.Svc.Query.Availability.AvailablePeriods.Get(ctx, id)
				if err != nil {
					return nil, mapGraphQLErr(err)
				}
				if got23 != nil {
					atx.Add(r.Svc.Mutation.Availability.AvailablePeriods.DeleteOp(got23.Id, new(availableperiodsql.DeleteAvailabilityAvailablePeriodsByIdResponse)))
					if id := got23.StartId; id != "" {
						got24, err := r.Svc.Query.Availability.CalendarTimes.Get(ctx, id)
						if err != nil {
							return nil, mapGraphQLErr(err)
						}
						if got24 != nil {
							atx.Add(r.Svc.Mutation.Availability.CalendarTimes.DeleteOp(got24.Id, new(calendartimesql.DeleteAvailabilityCalendarTimesByIdResponse)))
						}
					}
					if id := repox.Deref(got23.EndId); id != "" {
						got25, err := r.Svc.Query.Availability.CalendarTimes.Get(ctx, id)
						if err != nil {
							return nil, mapGraphQLErr(err)
						}
						if got25 != nil {
							atx.Add(r.Svc.Mutation.Availability.CalendarTimes.DeleteOp(got25.Id, new(calendartimesql.DeleteAvailabilityCalendarTimesByIdResponse)))
						}
					}
				}
			}
		}
		for _, v26 := range merged.GetAvailablePeriods() {
			n27 := availabilityAvailablePeriodToCreateInput(v26)
			n27.Id = repox.NewULID()
			n27.AvailabilityId = id
			if v28 := v26.GetStart(); v28 != nil {
				n29 := availabilityCalendarTimeToCreateInput(v28)
				n29.Id = repox.NewULID()
				atx.Add(r.Svc.Mutation.Availability.CalendarTimes.CreateOp(n29, new(calendartimesql.InsertAvailabilityCalendarTimesResponse)))
				n27.StartId = n29.Id
			}
			if v30 := v26.GetEnd(); v30 != nil {
				n31 := availabilityCalendarTimeToCreateInput(v30)
				n31.Id = repox.NewULID()
				atx.Add(r.Svc.Mutation.Availability.CalendarTimes.CreateOp(n31, new(calendartimesql.InsertAvailabilityCalendarTimesResponse)))
				n27.EndId = n31.Id
				n27.EndFormCase = "END"
			}
			atx.Add(r.Svc.Mutation.Availability.AvailablePeriods.CreateOp(n27, new(availableperiodsql.InsertAvailabilityAvailablePeriodsResponse)))
		}
	}
	*ops = append(*ops, utx...)
	resp := new(availabilitiesql.UpdateAvailabilityAvailabilitiesByIdResponse)
	etag := in.GetEtag()
	if etag != "" {
		ops.Add(r.Svc.Mutation.Availability.Availabilities.UpdateOp(id, availabilitiesql.UpdateInput{Id: graphql.Value(id)}, new(availabilitiesql.UpdateAvailabilityAvailabilitiesByIdResponse), availabilitiesql.Update().PostCheck(availabilitiesql.Etag.Eq(etag))))
		ops.Add(r.Svc.Mutation.Availability.Availabilities.UpdateOp(id, patch, resp, availabilitiesql.Update().PreCheck(availabilitiesql.Etag.Eq(etag))))
	} else {
		ops.Add(r.Svc.Mutation.Availability.Availabilities.UpdateOp(id, patch, resp))
	}
	if staleStart != "" {
		atx.Add(r.Svc.Mutation.Availability.CalendarTimes.DeleteOp(staleStart, new(calendartimesql.DeleteAvailabilityCalendarTimesByIdResponse)))
	}
	if staleEnd != "" {
		atx.Add(r.Svc.Mutation.Availability.CalendarTimes.DeleteOp(staleEnd, new(calendartimesql.DeleteAvailabilityCalendarTimesByIdResponse)))
	}
	*ops = append(*ops, atx...)
	return func(ctx context.Context, failed error) error {
		if failed == nil {
			if resp.AffectedRows == 0 {
				if etag != "" {
					return repox.ErrConflict
				}
				return repox.ErrNotFound
			}
			return nil
		}
		// The request failed; if this guard is why, say so.
		if etag != "" {
			if now, err := r.Svc.Query.Availability.Availabilities.Get(ctx, id); err == nil && (now == nil || availabilityFromRow(now).GetEtag() != etag) {
				return repox.ErrConflict
			}
		}
		return nil
	}, nil
}

