// Delete soft-deletes the record addressed by its resource name: delete_time
// is set, the row stays. The update time is set to the same instant: the
// delete is the record's latest write, which a reader by update time can tell
// from any write after it.
func (r *GraphQLAvailabilityRepository) Delete(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "calendars", "availabilities"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	if _, err := r.Svc.Mutation.Availability.Availabilities.UpdateIfMatch(ctx, id, r.deletePatch(), availabilitiesql.DeleteTime.IsNull(true)); err != nil {
		if errors.Is(err, graphql.ErrConflict) {
			return repox.ErrNotFound
		}
		return mapGraphQLErr(err)
	}
	return nil
}

// deletePatch is the write that soft-deletes a record now: Delete's, and a
// Batch's.
func (r *GraphQLAvailabilityRepository) deletePatch() availabilitiesql.UpdateInput {
	at := time.Now().UTC()
	now := at.Format(time.RFC3339Nano)
	patch := availabilitiesql.UpdateInput{DeleteTime: graphql.Value(now)}
	patch.UpdateTime = graphql.Value(now) // the delete is the record's latest write
	if r.Retention > 0 {
		patch.ExpireTime = graphql.Value(at.Add(r.Retention).Format(time.RFC3339Nano))
	}
	patch.Etag = graphql.Value(repox.NewULID())
	return patch
}

// Undelete clears the soft-delete mark and returns the restored record.
func (r *GraphQLAvailabilityRepository) Undelete(ctx context.Context, name string) (*availabilityv1.Availability, error) {
	id, err := r.rowID(ctx, name)
	if err != nil {
		return nil, err
	}
	patch := availabilitiesql.UpdateInput{DeleteTime: graphql.Null[string]()}
	patch.UpdateTime = graphql.Value(time.Now().UTC().Format(time.RFC3339Nano))
	patch.ExpireTime = graphql.Null[string]()
	patch.Etag = graphql.Value(repox.NewULID())
	if _, err := r.Svc.Mutation.Availability.Availabilities.UpdateIfMatch(ctx, id, patch, availabilitiesql.DeleteTime.IsNull(false)); err != nil {
		if !errors.Is(err, graphql.ErrConflict) {
			return nil, mapGraphQLErr(err)
		}
		if _, err := r.get(ctx, id); err != nil {
			return nil, err
		}
		return nil, fmt.Errorf("%w: %s is not deleted", repox.ErrAlreadyExists, name)
	}
	return r.get(ctx, id)
}

// Purge removes the record addressed by its resource name for good.
func (r *GraphQLAvailabilityRepository) Purge(ctx context.Context, name string) error {
	if _, err := repox.SplitName(name, "calendars", "availabilities"); err != nil {
		return err
	}
	if h := r.Hooks.BeforeDelete; h != nil {
		if err := h(ctx, name); err != nil {
			return err
		}
	}
	id, err := r.rowID(ctx, name)
	if err != nil {
		return err
	}
	_, err = r.purge(ctx, id, name, true)
	return err
}

// purge removes row id, named name, for good -- unless something still
// refers to it, when it keeps the row and reports kept: a row of this
// database holding a foreign key to it (asked first, then caught
// again from the database's own refusal), or, when askReferrers, a referrer
// in another database or service (r.Refs). A purge never fails, and never
// cascades, because of a referrer. repox.ErrNotFound when there is no such
// row.
func (r *GraphQLAvailabilityRepository) purge(ctx context.Context, id, name string, askReferrers bool) (kept bool, err error) {
	if askReferrers && r.Refs.KeepOnPurge(ctx, "the-protobuf-project.org/Availability", name) {
		return true, nil
	}
	err = r.remove(ctx, id)
	if repox.IsForeignKeyViolation(err) {
		r.Refs.Kept(ctx, name, "foreign key")
		return true, nil
	}
	return false, err
}

// PurgeExpired removes for good every deleted record whose expire_time is at
// or before now, keeping the ones something still refers to (see purge).
// Hooks do not run.
func (r *GraphQLAvailabilityRepository) PurgeExpired(ctx context.Context, now time.Time) (repox.PurgeResult, error) {
	var res repox.PurgeResult
	in := repox.ListInput{
		PageSize:    500,
		ShowDeleted: true,
		ReadMask:    []string{"name"},
		Where: []filterx.Condition{
			{Field: "delete_time", Op: filterx.OpNull, Value: "false"},
			{Field: "expire_time", Op: filterx.OpLte, Value: now.UTC().Format(time.RFC3339Nano)},
		},
	}
	for {
		page, next, err := r.list(ctx, in)
		if err != nil {
			return res, err
		}
		for _, m := range page {
			id, err := r.rowID(ctx, m.GetName())
			if errors.Is(err, repox.ErrNotFound) {
				continue // gone since the page was read
			}
			if err != nil {
				return res, err
			}
			kept, err := r.purge(ctx, id, m.GetName(), true)
			switch {
			case errors.Is(err, repox.ErrNotFound):
			case err != nil:
				return res, err
			case kept:
				res.Kept = append(res.Kept, m.GetName())
			default:
				res.Purged = append(res.Purged, m.GetName())
			}
		}
		if next == "" {
			return res, nil
		}
		in.PageToken = next
	}
}

// remove deletes row id with the value-object rows it owns.
func (r *GraphQLAvailabilityRepository) remove(ctx context.Context, id string) error {
	resp, err := r.Svc.Mutation.Availability.Availabilities.Delete(ctx, id)
	if err != nil {
		return mapGraphQLErr(err)
	}
	if resp.AffectedRows == 0 {
		return repox.ErrNotFound
	}
	for i := range resp.Returning {
		if id := repox.Deref(resp.Returning[i].StartId); id != "" {
			if _, err := r.Svc.Mutation.Availability.CalendarTimes.Delete(ctx, id); err != nil {
				return mapGraphQLErr(err)
			}
		}
	}
	for i := range resp.Returning {
		if id := repox.Deref(resp.Returning[i].EndId); id != "" {
			if _, err := r.Svc.Mutation.Availability.CalendarTimes.Delete(ctx, id); err != nil {
				return mapGraphQLErr(err)
			}
		}
	}
	dtx := r.Svc.Mutation.Tx()
	{
		rows13, err := r.Svc.Query.Availability.AvailablePeriods.List(ctx, availableperiodsql.List().Where(availableperiodsql.AvailabilityId.Eq(id)))
		if err != nil {
			return mapGraphQLErr(err)
		}
		for i := range rows13 {
			if id := rows13[i].Id; id != "" {
				got14, err := r.Svc.Query.Availability.AvailablePeriods.Get(ctx, id)
				if err != nil {
					return mapGraphQLErr(err)
				}
				if got14 != nil {
					dtx.Add(r.Svc.Mutation.Availability.AvailablePeriods.DeleteOp(got14.Id, new(availableperiodsql.DeleteAvailabilityAvailablePeriodsByIdResponse)))
					if id := got14.StartId; id != "" {
						got15, err := r.Svc.Query.Availability.CalendarTimes.Get(ctx, id)
						if err != nil {
							return mapGraphQLErr(err)
						}
						if got15 != nil {
							dtx.Add(r.Svc.Mutation.Availability.CalendarTimes.DeleteOp(got15.Id, new(calendartimesql.DeleteAvailabilityCalendarTimesByIdResponse)))
						}
					}
					if id := repox.Deref(got14.EndId); id != "" {
						got16, err := r.Svc.Query.Availability.CalendarTimes.Get(ctx, id)
						if err != nil {
							return mapGraphQLErr(err)
						}
						if got16 != nil {
							dtx.Add(r.Svc.Mutation.Availability.CalendarTimes.DeleteOp(got16.Id, new(calendartimesql.DeleteAvailabilityCalendarTimesByIdResponse)))
						}
					}
				}
			}
		}
	}
	if err := dtx.Commit(ctx); err != nil {
		return mapGraphQLErr(err)
	}
	return nil
}

// ListByKeys reads every record whose filter field field is one of keys; see
// repox.ListByKeys.
func (r *GraphQLAvailabilityRepository) ListByKeys(ctx context.Context, field string, keys []string, in repox.ListInput) ([]*availabilityv1.Availability, error) {
	return repox.ListByKeys(ctx, field, keys, in, func(ctx context.Context, in repox.ListInput) ([]*availabilityv1.Availability, string, error) {
		return r.List(ctx, "calendars/-", in)
	})
}

// Compile-time proof the adapter satisfies the interface.
var _ AvailabilityRepository = (*GraphQLAvailabilityRepository)(nil)

// graphQLBatch is Batch on GraphQL: queued writes go into the Unit's mutation
// request on Commit (see repox.Unit.Commit). A guarded UpdateOutputOnly runs
// ahead of it, one by one: the engine reports its failed guard by touching no
// row, which cannot abort a request.
type graphQLBatch struct {
	u         *repox.Unit
	svc       *freebusyql.Service
	retention time.Duration
	// keys holds the row key of every record this batch creates, by name: a
	// later write in the batch finds its row here, since it is not stored
	// until the batch's request runs.
	keys map[string]string
}

// Commit applies the Unit's writes; see repox.Unit.Commit.
func (b *graphQLBatch) Commit(ctx context.Context) error { return b.u.Commit(ctx) }

// rowID returns the row key of the record named name: one this batch creates,
// else what resolve (a repository's rowID) finds.
func (b *graphQLBatch) rowID(ctx context.Context, name string, resolve func(context.Context, string) (string, error)) (string, error) {
	if id, ok := b.keys[name]; ok {
		return id, nil
	}
	return resolve(ctx, name)
}

// CreateAvailability queues a create and returns the name the record will have.
func (b *graphQLBatch) CreateAvailability(parent string, in *availabilityv1.Availability) (string, error) {
	r := &GraphQLAvailabilityRepository{Svc: b.svc}
	ci, named, err := r.newInput(parent, in)
	if err != nil {
		return "", err
	}
	if b.keys == nil {
		b.keys = map[string]string{}
	}
	b.keys[named.GetName()] = ci.Id
	queueAvailabilityReferences(b.u, named, nil)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		return r.insertOps(ctx, ops, named, ci)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Availability", Name: named.GetName(), Op: repox.ChangeCreate, Record: named})
	return named.GetName(), nil
}

// UpdateAvailability queues Update; in.Etag, when set, guards it inside the
// batch's request (see updateOps).
func (b *graphQLBatch) UpdateAvailability(in *availabilityv1.Availability, paths []string) {
	if _, err := repox.SplitName(in.GetName(), "calendars", "availabilities"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLAvailabilityRepository{Svc: b.svc}
	queueAvailabilityReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, nil)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Availability", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getAvailability)})
}

// UpdateAvailabilityWithOutputOnly queues UpdateWithOutputOnly; in.Etag, when
// set, guards it inside the batch's request, as UpdateAvailability's does.
func (b *graphQLBatch) UpdateAvailabilityWithOutputOnly(in *availabilityv1.Availability, paths, outputPaths []string) {
	if _, err := repox.SplitName(in.GetName(), "calendars", "availabilities"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLAvailabilityRepository{Svc: b.svc}
	queueAvailabilityReferences(b.u, in, paths)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		return r.updateOps(ctx, ops, id, in, paths, outputPaths)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Availability", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getAvailability)})
}

// UpdateAvailabilityOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards
// it, and a guarded update runs ahead of the batch (see graphQLBatch).
func (b *graphQLBatch) UpdateAvailabilityOutputOnly(in *availabilityv1.Availability, paths []string) {
	if len(paths) == 0 {
		b.u.Fail(fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument))
		return
	}
	if _, err := repox.SplitName(in.GetName(), "calendars", "availabilities"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLAvailabilityRepository{Svc: b.svc}
	patch := availabilityToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Availability", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getAvailability)})
	if etag := in.GetEtag(); etag != "" {
		b.u.QueueGraphQLAhead(func(ctx context.Context) error {
			id, err := b.rowID(ctx, in.GetName(), r.rowID)
			if err != nil {
				return err
			}
			_, err = b.svc.Mutation.Availability.Availabilities.UpdateIfMatch(ctx, id, patch, availabilitiesql.Etag.Eq(etag))
			return mapGraphQLErr(err)
		})
		return
	}
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Availability.Availabilities.UpdateOp(id, patch, new(availabilitiesql.UpdateAvailabilityAvailabilitiesByIdResponse)))
		return nil, nil
	})
}

// DeleteAvailability queues a soft delete. A record already deleted or gone is
// not an error.
func (b *graphQLBatch) DeleteAvailability(name string) {
	if _, err := repox.SplitName(name, "calendars", "availabilities"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLAvailabilityRepository{Svc: b.svc, Retention: b.retention}
	queueAvailabilityDelete(b.u, name, false)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Availability.Availabilities.UpdateOp(id, r.deletePatch(), new(availabilitiesql.UpdateAvailabilityAvailabilitiesByIdResponse), availabilitiesql.Update().PreCheck(availabilitiesql.DeleteTime.IsNull(true))))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Availability", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getAvailability)})
}

// PurgeAvailability queues the record's removal for good. A record already
// gone is not an error.
func (b *graphQLBatch) PurgeAvailability(name string) {
	if _, err := repox.SplitName(name, "calendars", "availabilities"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLAvailabilityRepository{Svc: b.svc, Refs: b.u.Conn().References}
	// A record a referrer in another database or service names is kept, as
	// Purge keeps it. One a foreign key of
	// this database still names fails the commit with
	// repox.ErrForeignKey: the request is one transaction, and the engine
	// cannot skip one of its mutations.
	keep := queueAvailabilityPurge(b.u, name)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		if *keep {
			return nil, nil
		}
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		return r.purgeOps(ctx, ops, id)
	})
	b.u.Record(repox.Change{Type: "the-protobuf-project.org/Availability", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getAvailability)})
}
